package com.ascensionlib.laboratory;

import static org.junit.jupiter.api.Assertions.*;

import com.cobbleascend.domain.v1.LaboratoryLoot;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;

/** The laboratory data is generated by tools/laboratory_structures.py; this keeps it in step with the Java that reads it. */
class LaboratoryDataTest {
    private JsonObject json(String path) {
        var stream = getClass().getResourceAsStream("/data/ascensionlib/" + path);
        assertNotNull(stream, "Missing " + path + "; run tools/laboratory_structures.py");
        return JsonParser.parseReader(new InputStreamReader(stream, StandardCharsets.UTF_8)).getAsJsonObject();
    }

    @Test void everyContainerHasAnEmptyMarkerAndAFillerTable() {
        for (var container : LaboratoryLoot.Container.values()) {
            var marker = json("loot_table/" + Laboratories.MARKER_PREFIX + container.id() + ".json");
            assertEquals(0, marker.getAsJsonArray("pools").size(), "a marker must stay empty, so unpacking one yields nothing");
            var filler = json("loot_table/" + Laboratories.FILLER_PREFIX + container.id() + ".json");
            assertFalse(filler.toString().contains("ascensionlib:currency"), "materials are paid by LaboratoryLoot, never by the filler table");
        }
    }

    @Test void theStructureIsTheOneTheJavaLooksUp() {
        var structure = json("worldgen/structure/laboratory.json");
        assertEquals("minecraft:jigsaw", structure.get("type").getAsString());
        assertEquals(Laboratories.STRUCTURE.location().toString(),
                json("worldgen/structure_set/laboratory.json").getAsJsonArray("structures").get(0).getAsJsonObject().get("structure").getAsString());
        var placement = json("worldgen/structure_set/laboratory.json").getAsJsonObject("placement");
        assertEquals(48, placement.get("spacing").getAsInt());
        assertEquals(16, placement.get("separation").getAsInt());
    }

    @Test void guardsSpawnOnlyInsideTheLaboratory() {
        for (var spawn : json("spawn_pool_world/laboratory.json").getAsJsonArray("spawns")) {
            var structures = spawn.getAsJsonObject().getAsJsonObject("condition").getAsJsonArray("structures");
            assertEquals(1, structures.size());
            assertEquals(Laboratories.STRUCTURE.location().toString(), structures.get(0).getAsString());
        }
    }

    @Test void everyTemplateInThePoolsShipsInTheJar() {
        for (var pool : new String[] {"start", "hub", "halls", "rooms", "core"}) {
            for (var element : json("worldgen/template_pool/laboratory/" + pool + ".json").getAsJsonArray("elements")) {
                var location = element.getAsJsonObject().getAsJsonObject("element").get("location").getAsString();
                var path = "/data/ascensionlib/structure/" + location.substring(location.indexOf(':') + 1) + ".nbt";
                assertNotNull(getClass().getResourceAsStream(path), "Missing template " + path);
            }
        }
    }
}
